m_proto_ResidentLetter.signature:
type ResidentLetter struct {
	// Session 寻址命中所在会话房间 id（session:<n>）。
	Session string
	// Count 本批命中该驻场者地址的消息条数（≥1）。
	Count int
	// MinSeq / MaxSeq 本批命中消息的账本 seq 区间（含两端）。
	MinSeq, MaxSeq int64
}

m_proto_SessionResident.signature:
type SessionResident struct {
	// Session 会话房间 id（session:<n>）。
	Session string `json:"session"`
	// Identity 驻场者成员身份，统一记法 user:<name> / agent:<name>（identity.go）。
	Identity string `json:"identity"`
	// DesktopSession Claude 桌面端会话 id（local_…）；continue 深链用。
	DesktopSession string `json:"desktop_session,omitempty"`
	// CLISession 该桌面端会话的 CLI 会话 id：信箱文件名键（mod 以 $.session.id() 取同值）。
	CLISession string `json:"cli_session,omitempty"`
	// Machine 桌面端所在机器；空串 = 本机。
	Machine string `json:"machine,omitempty"`
	// SatAt 登记时刻。
	SatAt time.Time `json:"sat_at"`
}

m_proto_RoomHistoryItem.signature:
type RoomHistoryItem struct {
	LedgerEvent
	NoRecipient NoRecipientReason `json:"no_recipient,omitempty"`
}

m_proto_SessionCard.signature:
type SessionCard struct {
	CardID string `json:"card_id"`
	Title  string `json:"title"`
	Status string `json:"status"`
	// Seat 该卡当前席位身份；空串 = 还没配人（虚线卡）。
	Seat string `json:"seat,omitempty"`
	// SeatMode 该卡席位驱动模式（B435：push|pull）；空座不出键。键名不用 mode，
	// 避免与 CoordinatorRebindReq.Mode（换绑方式 launch）同名异义。
	SeatMode string `json:"seat_mode,omitempty"`
}

m_proto_SessionSummary.signature:
type SessionSummary struct {
	ID   string `json:"id"`   // session:<n>，不透明
	Kind string `json:"kind"` // SessionKind
	// Title 会话标题（人/主 agent 新建时给）。
	Title string `json:"title"`
	// Owner 群主身份（升级终点）：人 或 主 agent 会话身份。
	Owner string `json:"owner"`
	// Archived 显式归档；归档后只读。卡的终态不等于会话结束。
	Archived bool `json:"archived"`
	// Project 项目房间标记（B435 ⑤/D6）：取值项目名；非项目房间不出键。
	// 唯一写者是项目房间绑定（session sit --project / project room 创建的那条）。
	Project string `json:"project,omitempty"`
	// Unread 该成员未读消息数。
	Unread int `json:"unread"`
	// NeedsHuman 会话内任意一张卡处于 needs_human（列表标签）。
	NeedsHuman   bool            `json:"needs_human"`
	LastActivity time.Time       `json:"last_activity"`
	Preview      *RoomPreview    `json:"preview,omitempty"`
	Members      []SessionMember `json:"members,omitempty"`
	Cards        []SessionCard   `json:"cards,omitempty"`
}

m_collab_client_LedgerClient.signature:
type LedgerClient interface {
	// GetCard 读卡（含 driver_session 绑定投影与终态判定所需字段）。
	GetCard(id string) (proto.Card, error)
	// ListActiveCards 列项目范围内「已开始未结束」的卡（成员派生规则的输入；
	// project 空 = 跨项目）。Status ∉ {已完成, 终止} 即在列。
	ListActiveCards(project string) ([]proto.Card, error)
	// ListAllCards 列项目范围内全部卡（含终态与并入成员）：账本
	// ListCards{IncludeTerminal:true} 的直通镜像（B156.2 岔口一方案甲还债
	// 直通）。终态房间「沉底可列」与并入只读判定（Following 非空）的唯一
	// 枚举源。注意 Following 只在列表方法上有值：GetCard 走单卡读、不派生
	// 跟随态，恒为空串。
	ListAllCards(project string) ([]proto.Card, error)
	// RecordRoomMessage 发布房间消息事件（卡房间 cardID=卡号；群级传空串）。
	RecordRoomMessage(cardID string, msg proto.RoomMessage, actor string) (int64, error)
	// RecordMessageConsumed 落恰好一次的消费标记（幂等由账本事务保证）。
	RecordMessageConsumed(cardID string, msgSeq int64, consumer string) error
	// EventsFromAsc 升序游标读事件（cardIDs 空 = 全流含群级无卡事件）。
	EventsFromAsc(cardIDs []string, fromSeq int64, limit int) ([]proto.LedgerEvent, error)
	// EventsFromAscContext 供 HTTP 会话读取在客户端断开时取消事件流查询。
	EventsFromAscContext(ctx context.Context, cardIDs []string, fromSeq int64, limit int) ([]proto.LedgerEvent, error)
	// RoomMessagesBeforeContext 只读指定房间最近消息；beforeSeq 为排他上界，limit 必须为正。
	RoomMessagesBeforeContext(ctx context.Context, roomID string, beforeSeq int64, limit int) ([]proto.LedgerEvent, error)
	// RoomMessageSnapshotsContext 批量返回目标 room 最新消息、最大 created_at 与给定 seq 水位之后的消息行数。
	// 房间身份按 RoomIDOf 语义解析：card_id 优先，无卡事件才取 payload.room；不解释 member/unread。
	RoomMessageSnapshotsContext(ctx context.Context, afterByRoom map[string]int64) ([]RoomMessageSnapshot, error)
	// SessionProjectionEventsContext 返回单会话结构事件及调用方给定当前成员卡上的投影事件。
	SessionProjectionEventsContext(ctx context.Context, sessionID string, cardIDs []string) ([]proto.LedgerEvent, error)
	// LatestNeedsEventsContext 返回每张指定卡最新一条 needs_human/needs_cleared 事实。
	LatestNeedsEventsContext(ctx context.Context, cardIDs []string) ([]proto.LedgerEvent, error)
	// --- B409 U5 收件箱限域读（recipient-address 候选；U4/U5 seam 清点见
	// internal/ledger/message_candidates.go 文件头——与 U4 的范围投影读无共同方法）---
	// MentionCandidatesContext 读一页 mentions 精确含 member 的 room_message 候选
	// 超集。roomID 非空时限房间（SameRoom 的 SQL 超集：挂卡行按 card_id、无卡行
	// 按 payload.room——SameRoom 权威判定仍由调用方执行）；cardlessOnly 只取无卡
	// 行（Pending 群级源）；afterSeq 排他；limit 必须 >0。kind/by_system 不在账本
	// 过滤——裁决在 collab。
	MentionCandidatesContext(ctx context.Context, member, roomID string, cardlessOnly bool, afterSeq int64, limit int) ([]proto.LedgerEvent, error)
	// CardRoomUserMessagesContext 读给定卡集合上 kind=user 的房间消息行（Pending
	// 第二源）。cardIDs 空返回空集；块间各自升序，跨源归并排序由调用方负责。
	CardRoomUserMessagesContext(ctx context.Context, cardIDs []string, afterSeq int64, limit int) ([]proto.LedgerEvent, error)
	// ConsumedMessageSeqsContext 读 consumer 已消费的 message_seq 集合（载荷
	// message_seq/consumer 精确匹配为权威）。afterSeq 是安全上界：标记事件 seq
	// 必大于被标记消息 seq，故不会漏掉 message_seq>afterSeq 的相关标记。
	ConsumedMessageSeqsContext(ctx context.Context, consumer string, afterSeq int64) ([]int64, error)
	// EventBySeq 按全局 seq 点读单条事件（Consume 定位消息所属卡的限域替身）；
	// ok=false 表示 seq 不存在。
	EventBySeq(seq int64) (proto.LedgerEvent, bool, error)
	// --- B358 会话（群）域账本能力 ---
	// CreateSession 建一场会话（群），返回带分配 id 的会话本体。
	CreateSession(title, owner, actor string) (proto.Session, error)
	// GetSession 读单会话；不存在返回错误（由组装点翻译为 ErrNoRoom）。
	GetSession(id string) (proto.Session, error)
	// ListSessions 列全部会话（含归档），按创建序。
	ListSessions() ([]proto.Session, error)
	// ArchiveSession 显式归档会话；归档后只读，幂等。
	ArchiveSession(id, actor string) error
	// JoinCardToSession 把卡拉进会话；卡已属其它会话时返回错误。
	JoinCardToSession(sessionID, cardID, actor string) error
	// LeaveCardToSession 把卡移出会话；幂等。
	LeaveCardToSession(sessionID, cardID, actor string) error
	// SessionOfCard 返回该卡当前所属会话 id；不属于任何会话返回空串。
	SessionOfCard(cardID string) (string, error)
	// AddSessionMember 把一个显式成员（人或主 agent 外部会话身份）记入会话。
	AddSessionMember(sessionID, identity, actor string) error
	// SessionResident 读会话房间的驻场者登记（B435 D5，一房间至多一名）；ok=false 表示
	// 无驻场者（不是错误）。匹配函数的默认收件人与驻场者地址解析只经它读驻场者。
	SessionResident(sessionID string) (proto.SessionResident, bool, error)
	// BindDriver 绑定/换绑（expect=CAS 前值；实现侧落 EvDriverTakeover 审计）。
	BindDriver(id, session, carrier, expect string) error
	// DriverLease 读绑定者活性租约：过期时刻 + 行是否存在。不过滤过期，
	// 活性判定由调用方按同一时钟做。
	DriverLease(session string) (time.Time, bool, error)
}
